import{c as o,Q as t,j as s,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Anthropic publicó la mejor clase de prompting que he visto — análisis","description":"","frontmatter":{"url":"https://x.com/yerocode0/status/2070492880884367593","title":"Anthropic publicó la mejor clase de prompting que he visto — análisis","author":"Yero","archived":"2026-06-27T00:00:00.000Z","duration":"00:24:10","handle":"@Yerocode0","published":"2026-06-26T00:00:00.000Z","subtitle_lang":"Spanish (混合英語)","type":"video"},"headers":[],"relativePath":"research/tweets/2026-06-26-yerocode0-2070492880884367593.md","filePath":"research/tweets/2026-06-26-yerocode0-2070492880884367593.md","lastUpdated":1785909234000}'),a={name:"research/tweets/2026-06-26-yerocode0-2070492880884367593.md"};function r(i,e,p,l,g,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="anthropic-publico-la-mejor-clase-de-prompting-que-he-visto-—-analisis-—-yerocode0" tabindex="-1">Anthropic publicó la mejor clase de prompting que he visto — análisis — @Yerocode0 <a class="header-anchor" href="#anthropic-publico-la-mejor-clase-de-prompting-que-he-visto-—-analisis-—-yerocode0" aria-label="Permalink to &quot;Anthropic publicó la mejor clase de prompting que he visto — análisis — @Yerocode0&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/yerocode0/status/2070492880884367593" target="_blank" rel="noreferrer">https://x.com/yerocode0/status/2070492880884367593</a><strong>作者</strong>: Yero (@Yerocode0) <strong>發布日期</strong>: 2026-06-26 <strong>收錄日期</strong>: 2026-06-27 <strong>時長</strong>: 00:24:10 <strong>語言</strong>: 西班牙語（夾雜英語）</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>Anthropic 官方示範如何用「迭代式 Prompt Engineering」逐步精煉 Claude 提示詞，以車禍保險理賠表單分析為真實案例貫穿全程。</p></blockquote><ul><li>提示詞工程是<strong>迭代式實驗科學</strong>：從任務描述出發，逐版本測試並觀察 Claude 的輸出差異</li><li>結構化提示詞的核心五要素：任務描述（Task Description）、逐步指令（Step-by-step Instructions）、背景文件（Background/Documents）、範例（Examples）、輸出格式控制（Output Format）</li><li><strong>背景資訊內建</strong>（Baking context in）：將表單結構說明直接放入 system prompt，可讓 Claude 輸出更準確、更簡潔，不需大量敘述</li><li><strong>Few-shot 範例</strong>的威力：提供真實難例（edge cases）後，Claude 的判斷置信度和一致性顯著提升</li><li>Claude 4 / 3.7 的 <strong>Extended Thinking</strong>（延伸思考模式）可作為提示詞品質不足時的補救手段，並透過 <code>&lt;thinking&gt;</code> 標籤暴露推理過程供除錯</li></ul><hr><h2 id="整理版-可讀逐字稿" tabindex="-1">整理版（可讀逐字稿） <a class="header-anchor" href="#整理版-可讀逐字稿" aria-label="Permalink to &quot;整理版（可讀逐字稿）&quot;">​</a></h2><h3 id="課程背景與應用場景-00-00–03-44" tabindex="-1">課程背景與應用場景（00:00–03:44） <a class="header-anchor" href="#課程背景與應用場景-00-00–03-44" aria-label="Permalink to &quot;課程背景與應用場景（00:00–03:44）&quot;">​</a></h3><p>本課程由 Anthropic applied AI 團隊成員示範，以「瑞典車禍保險理賠表單自動分析」作為貫穿案例。場景是：理賠系統接收到一張手繪事故草圖和一份有 17 個 checkbox 的標準表單，要求 Claude 判斷肇事方。</p><p>第一版 prompt 僅給最基本指示，Claude 的輸出存在問題：誤判為滑雪事故（非車禍），顯示在沒有足夠背景資訊時 Claude 會自行補充假設。這引出課程核心論點——<strong>提示詞工程是迭代的實驗科學</strong>，每個版本需要設立可驗證的成功條件。</p><h3 id="五大最佳實踐-03-44–08-23" tabindex="-1">五大最佳實踐（03:44–08:23） <a class="header-anchor" href="#五大最佳實踐-03-44–08-23" aria-label="Permalink to &quot;五大最佳實踐（03:44–08:23）&quot;">​</a></h3><p>講者整理 Anthropic 內部及對外推薦的 prompt 最佳實踐：</p><ol><li><strong>任務描述（Task Description）</strong>：開門見山告訴 Claude「你是誰、你在做什麼」，建立明確角色定位</li><li><strong>逐步指令（Step-by-step Instructions）</strong>：像清單一樣列出推理步驟，引導 Claude 的思考路徑</li><li><strong>背景資料（Background/Data/Documents）</strong>：把系統能提前知道的資訊（如表單結構、業務規則）事先嵌入</li><li><strong>範例（Examples）</strong>：提供 few-shot 示範，尤其是邊界難例</li><li><strong>輸出格式（Output Format）</strong>：明確指定回覆格式，包括 XML tag、JSON 結構，或使用 pre-fill 技術</li></ol><p>第二版加入 AI Assistant 角色描述（在 Swedish 保險環境下工作），Claude 立即能正確辨識這是車禍而非滑雪事故，並準確讀出 checkbox 1（Vehicle A）和 checkbox 12（Vehicle B）的勾選狀態。</p><h3 id="背景資訊內建的效果-08-23–12-41" tabindex="-1">背景資訊內建的效果（08:23–12:41） <a class="header-anchor" href="#背景資訊內建的效果-08-23–12-41" aria-label="Permalink to &quot;背景資訊內建的效果（08:23–12:41）&quot;">​</a></h3><p>第三版將表單 17 個 checkbox 的含義全部內建到 system prompt（說明每一行代表什麼情境、兩欄分別對應哪輛車）。效果顯著：Claude 不再花時間「敘述表單結構」，而是直接分析並給出明確結論——Vehicle B 為肇事方，並列出具體依據。</p><p><strong>靜態背景知識應當預先嵌入，而非每次透過 user prompt 重新提供。</strong></p><h3 id="few-shot-範例與對話歷史-12-41–15-42" tabindex="-1">Few-shot 範例與對話歷史（12:41–15:42） <a class="header-anchor" href="#few-shot-範例與對話歷史-12-41–15-42" aria-label="Permalink to &quot;Few-shot 範例與對話歷史（12:41–15:42）&quot;">​</a></h3><p>當案例存在灰色地帶時（如 checkbox 資訊不完整），few-shot 範例可提供 Claude 決策錨點。講者示範用 XML tag 包裹範例案例（<code>&lt;example&gt;</code>）。對於需要長期追蹤的用戶交互場景，**對話歷史（conversation history）**也應當納入 system prompt 作為上下文豐富化手段。</p><h3 id="明確輸出格式與-pre-fill-15-42–23-11" tabindex="-1">明確輸出格式與 Pre-fill（15:42–23:11） <a class="header-anchor" href="#明確輸出格式與-pre-fill-15-42–23-11" aria-label="Permalink to &quot;明確輸出格式與 Pre-fill（15:42–23:11）&quot;">​</a></h3><p>要讓 Claude 輸出可被下游系統解析的結構，可透過兩種方式：</p><ul><li><strong>Output format 指定</strong>：在 system prompt 中說明回覆必須包含 <code>&lt;final_verdict&gt;</code> XML tag 包裹最終結論</li><li><strong>Pre-fill 技術</strong>：在 assistant turn 預先填入開頭（如 <code>&lt;final_verdict&gt;</code>），強迫 Claude 從此格式起始，略過不需要的前言</li></ul><h3 id="extended-thinking-作為補充工具-23-11–24-10" tabindex="-1">Extended Thinking 作為補充工具（23:11–24:10） <a class="header-anchor" href="#extended-thinking-作為補充工具-23-11–24-10" aria-label="Permalink to &quot;Extended Thinking 作為補充工具（23:11–24:10）&quot;">​</a></h3><p>Claude 3.7 和 Claude 4 提供的 Extended Thinking 可彌補提示詞不夠精細的缺口。透過 <code>&lt;thinking&gt;</code> 標籤，開發者可觀察 Claude 的推理過程以進一步優化 prompt。建議：優先用明確提示詞引導，把 Extended Thinking 當作除錯工具或高難度任務的輔助，而非常規依賴。</p><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><p><strong>[00:00 → 00:02]</strong> aplAdeiCeM, here at Anthropic,</p><p><strong>[00:02 → 00:05]</strong> and with me is Christian, also part of the AppAdeiCeM.</p><p><strong>[00:05 → 00:06]</strong> And what we&#39;re going to do today</p><p><strong>[00:06 → 00:09]</strong> is take you through a little bit of prompting best practices,</p><p><strong>[00:09 → 00:11]</strong> and we&#39;re going to use a real-world scenario</p><p><strong>[00:11 → 00:14]</strong> and build up a prompt together.</p><p><strong>[00:14 → 00:25]</strong> So a little bit about what prompt engineering is. fireplace engineering.</p><p><strong>[00:26 → 00:29]</strong> This is the</p><p><strong>[00:30 → 00:57]</strong> que necesitas completar el task y pensar en cómo</p><p><strong>[02:57 → 03:13]</strong> in the sense that in our problem we actually haven&#39;t done anything to set the stage on what is actually taking place here so this sort of first guess is not too bad but we still notice a lot of intuition that we can bake into thought so we switch back to slides.</p><p><strong>[03:13 → 03:23]</strong> You can see here that in many ways prompt engineering is very iterative empirical science and in this case here we could almost have a test case where</p><p><strong>[03:23 → 03:36]</strong> we can make sure it understands it&#39;s in the core or vehicular environment nothing to do with skiing and in that way you iteratively build it from your prompt to make sure it&#39;s actually tacking the problem you&#39;re intending to solve.</p><p><strong>[03:36 → 03:44]</strong> And to do so go through some best practices of how we we an anthropic practice down internally or recommend others to do so as well.</p><p><strong>[03:44 → 03:46]</strong> So we&#39;re going to talk about some best practices for developing a great prompt. First, we want to talk a little bit</p><p><strong>[04:15 → 04:23]</strong> that we recommend is setting the task description up front so telling cloud what are you here to do, what&#39;s your role, what task are you trying to accomplish today.</p><p><strong>[04:24 → 04:34]</strong> So in this case it&#39;s the image that Christian was showing form and the drawing of the accident and how they</p><p><strong>[04:34 → 04:47]</strong> are streaming from another system depending on your use case. We&#39;re going to get some detailed instructions to cloud so almost like a step by step list of how we want to go through the task and how we want it to tackle the reasoning.</p><p><strong>[04:47 → 04:53]</strong> We may get some examples to cloud. Here&#39;s an example of if some piece of content you might receive, here&#39;s how you should respond when given that</p><p><strong>[05:04 → 05:09]</strong> que son estratégicas y luego, te va a hablar de qué se puede hacer el trabajo.</p><p><strong>[05:09 → 05:13]</strong> Aquí, con otro view, se ha un poco más detalle, un poco más?</p><p><strong>[05:13 → 05:17]</strong> Y vamos a tener cada una de estos 10 puntos individuales y ayer,</p><p><strong>[05:17 → 05:20]</strong> se ha hecho un poco de esto en el consul.</p><p><strong>[05:20 → 05:25]</strong> Entonces, la primera vez que la gente se va a hablar de la tasa y la tasa de tono.</p><p><strong>[05:25 → 05:29]</strong> Perfecto, entonces, si vamos a empezar con la tasa de tono,</p><p><strong>[05:29 → 05:31]</strong> como se ha realizado cuando yo me he llegado un poco de demo</p><p><strong>[05:31 → 05:33]</strong> no hemos tenido mucho elaborado</p><p><strong>[05:33 → 05:36]</strong> el scenario que está trabajando</p><p><strong>[05:36 → 05:39]</strong> en el caso de que también te sea</p><p><strong>[05:39 → 05:41]</strong> que el juego no necesariamente</p><p><strong>[05:41 → 05:43]</strong> hay un poco más de lo que uno de ellos</p><p><strong>[05:43 → 05:43]</strong> en nuestro caso, si quieres abrir a tu</p><p><strong>[05:43 → 05:46]</strong> tiempo, te va a dar más claridad de instrucciones</p><p><strong>[05:46 → 05:48]</strong> y también te va a hacer</p><p><strong>[05:48 → 05:50]</strong> lo que es el caso que tenemos que hacer</p><p><strong>[05:50 → 05:51]</strong> en el caso de que le vamos a hacer</p><p><strong>[05:51 → 05:53]</strong> en el caso de que también nos vamos a hacer</p><p><strong>[05:53 → 05:55]</strong> un poco de tón en tito</p><p><strong>[05:55 → 05:57]</strong> y aquí hay un juego que es</p><p><strong>[05:57 → 06:00]</strong> es que uno es clobo para decir factual, para decir confidentes.</p><p><strong>[06:00 → 06:03]</strong> Entonces, si clobo se puede entender lo que está mirando,</p><p><strong>[06:03 → 06:06]</strong> no quiero desgastar y hacer mis vidos.</p><p><strong>[06:06 → 06:08]</strong> Quiero hacerse ningún acesemento.</p><p><strong>[06:08 → 06:10]</strong> En nuestro caso, queremos hacerse que podemos</p><p><strong>[06:10 → 06:12]</strong> entender los que están faltando aquí.</p><p><strong>[06:12 → 06:14]</strong> Quiero hacerse, el acesemento es claro</p><p><strong>[06:14 → 06:15]</strong> y es confundido posible,</p><p><strong>[06:15 → 06:18]</strong> si no, no, no es lo que estamos haciendo.</p><p><strong>[06:18 → 06:21]</strong> Entonces, si vamos a ir a la consola,</p><p><strong>[06:21 → 06:24]</strong> podemos ir a un v2 que tenemos aquí.</p><p><strong>[06:24 → 06:27]</strong> Entonces, vamos a ir a un v2.</p><p><strong>[06:27 → 06:29]</strong> Y puedes ver aquí.</p><p><strong>[06:29 → 06:31]</strong> También, vamos a hacer el data.</p><p><strong>[06:31 → 06:32]</strong> Porque no lo hicimos</p><p><strong>[06:32 → 06:34]</strong> porque estamos viendo algo en el momento de que estamos viendo.</p><p><strong>[06:34 → 06:34]</strong> Entonces, lo que estamos viendo aquí es que el car</p><p><strong>[06:34 → 06:38]</strong> acesemento report.</p><p><strong>[06:38 → 06:40]</strong> Y es sólo 17 diferentes checkboxes,</p><p><strong>[06:40 → 06:42]</strong> que se puede ver lo que ha pasado.</p><p><strong>[06:42 → 06:44]</strong> Y puedes ver que hay un v2 a y un v2 a,</p><p><strong>[06:44 → 06:46]</strong> y un v2 a, en el lado de la derecha.</p><p><strong>[06:46 → 06:47]</strong> Y la propiedad de la misma manera,</p><p><strong>[06:47 → 06:49]</strong> es que vamos a hacer una cosa que se puede entender,</p><p><strong>[06:49 → 06:52]</strong> este manual y generar el data,</p><p><strong>[06:52 → 06:54]</strong> para acesementar lo que está pasando.</p><p>[... 共 322 segments，完整逐字稿見 /tmp/claude-scratch/out/yerocode0.txt ...]</p>',92)])])}const u=o(a,[["render",r]]);export{h as __pageData,u as default};
